SET SERVEROUTPUT ON
DECLARE
  v_mat    etudiant.matricule%TYPE := &p_mat;
  v_nom    etudiant.nom%TYPE;
  v_prenom etudiant.prenom%TYPE;
BEGIN
  SELECT nom, prenom INTO v_nom, v_prenom FROM etudiant WHERE matricule = v_mat;
  DBMS_OUTPUT.PUT_LINE(v_nom || ' ' || v_prenom);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Etudiant introuvable');
END;
/
- SELECT ... INTO : exactement une ligne, sinon NO_DATA_FOUND, traité dans EXCEPTION.

CREATE OR REPLACE FUNCTION moyenneetudiant (p_mat IN NUMBER, p_annee IN NUMBER) RETURN NUMBER IS
  v_moy NUMBER;
BEGIN
  SELECT ROUND(SUM(n.valeur * m.coefficient) / SUM(m.coefficient), 2) INTO v_moy
  FROM note n JOIN matiere m ON m.codematiere = n.codematiere
  WHERE n.matricule = p_mat AND n.annee = p_annee;
  RETURN NVL(v_moy, 0);
END moyenneetudiant;
/
SELECT matricule, moyenneetudiant(matricule, 2025) FROM etudiant;
- Un agrégat sans ligne renvoie une ligne contenant NULL (pas d'exception NO_DATA_FOUND) : NVL(v_moy, 0) donne 0.

CREATE OR REPLACE TRIGGER trg_note_valide
BEFORE INSERT OR UPDATE OF valeur ON note
FOR EACH ROW
BEGIN
  IF :NEW.valeur IS NULL OR :NEW.valeur NOT BETWEEN 0 AND 20 THEN
    RAISE_APPLICATION_ERROR(-20201, 'La note doit etre comprise entre 0 et 20');
  END IF;
END;
/
- BEFORE pour refuser avant l'écriture ; UPDATE OF valeur : seulement si la colonne est modifiée.
